INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('a6160774-179c-5877-b693-313a86fa5370', 'At Kestanesi', 'Aesculus hippocastanum L.', 'Essin (triterpen saponin)', 'Venotonik, ödem azaltıcı', 'Antikoagülan/Antiplatelet ilaçlar (warfarin, heparin, apiksaban, rivaroksaban vb.)', 'Eskülin bileşeni antitrombotik etkilere sahiptir; kanama riskini artırabilir.', 'yok', 'Antikoagülan/Antiplatelet alan hastalar', 'Bu kombinasyona karşı dikkatli olun. Sağlık uzmanınızla görüşün.', '1. Brinker F. Herb Contraindications and Drug Interactions. 2nd ed. Sandy, OR: Eclectic Medical Publications, 1998.', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('e3e8f6c9-964e-5b4f-9a24-2414fbe4c633', 'Beta Glukan', 'Saccharomyces cerevisiae', 'Beta glukan (polisakkarit)', 'Bağışıklık sistemi güçlendirme, LDL düşürme', '', '', '', '', '', '', '') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('859976af-200c-5af4-94d2-f3bb5c3ee8c1', 'Beta Glukan', 'Saccharomyces cerevisiae', 'Beta glukan (polisakkarit)', 'Bağışıklık sistemi güçlendirme, LDL düşürme', 'Antihipertansif ilaçlar (Kalsiyum kanal blokörleri, ACE inhibitörleri, ARB, Diüretikler, Beta blokörler gibi)', 'Klinik araştırmalar, beta-glukanların bazı hipertansif bireylerde sistolik ve diyastolik kan basıncını düşürebileceğini göstermektedir. Teorik olarak, beta-glukanların antihipertansif ilaçlarla birlikte alınması hipotansiyon riskini artırabilir.', 'X', '1. Vücut kitle indeksi büyük hastalar. 2.Kan basıncını düşüren ilaç alan hastalar.', 'Bu kombinasyona karşı dikkatli olun. Sağlık uzmanınızla görüşün.', '1. RxList. Beta-Glucans: Uses, Side Effects, Interactions, Dosage, and Warning. RxList. Updated 2025. Accessed September 8, 2025. https://www.rxlist.com/supplements/beta-glucans.htm 2. HelloPharmacist. Beta-glucans Interactions Overview. HelloPharmacist. Accessed September 8, 2025. 3. Maki, K., Galant, R., Samuel, P. et al. Effects of consuming foods containing oat β-glucan on blood pressure, carbohydrate metabolism and biomarkers of oxidative stress in men and women with elevated blood pressure. Eur J Clin Nutr 61, 786–795 (2007). https://doi.org/10.1038/sj.ejcn.1602562', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('b9e1b66c-b951-5392-91ef-355247b97e2f', 'Beta Glukan', 'Saccharomyces cerevisiae', 'Beta glukan (polisakkarit)', 'Bağışıklık sistemi güçlendirme, LDL düşürme', 'İmmunsupresan ilaçlar: (azatiyoprin, siklosporin, mikofenolat, takrolimus, sirolimussteroidler, kemoterapötikler)', 'Bazı klinik araştırmalar beta-glukanların immünostimülan etkilere sahip olduğunu göstermektedir. Teorik olarak beta-glukanlar immünosüpresif tedavinin etkisini azaltabilirler.', 'X', 'Organ nakli hastaları, Otoimmun hastalık tedavisi görenler (lupus, romatoid artrit, inflamatuar bağırsak hastalıkları gibi), kemoterapi/radyoterapi alan kanser tanılı hastalar', 'İmmünsüpresif tedavi gören hastalarda beta-glukan kullanımı bağışıklık yanıtını artırarak ilaç etkinliğini azaltabilir ve klinik risk oluşturabilir. Bu nedenle beta-glukan kullanımı organ nakli, otoimmün hastalık ve onkoloji hastalarında yalnızca hekim gözetiminde ve yakın izlem altında düşünülmelidir. Sağlık uzmanınızla görüşün.', '1. RxList. Beta-Glucans: Uses, Side Effects, Interactions, Dosage, and Warning. RxList. Updated 2025. Accessed September 8, 2025. https://www.rxlist.com/supplements/beta-glucans.htm 2. HelloPharmacist. Beta-glucans Interactions Overview. HelloPharmacist. Accessed September 8, 2025.', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('15c0d933-94fd-546d-a25f-4cd3db99d0a4', 'Beta Glukan', 'Saccharomyces cerevisiae', 'Beta glukan (polisakkarit)', 'Bağışıklık sistemi güçlendirme, LDL düşürme', 'İndometeazin', 'Beta-glukanların indometazin ilacıyla birlikte alınması, indometazine bağlı yaşamı tehdit eden yan etki riskini artırabilir. Bu olası etkileşim hakkında daha fazla bilgi edinilene kadar, beta-glukanları indometazinle birlikte alırken dikkatli olun.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun. Sağlık uzmanınızla görüşün.', 'RxList. Beta-Glucans: Uses, Side Effects, Interactions, Dosage, and Warning. RxList. Accessed September 8, 2025. https://www.rxlist.com/supplements/beta-glucans.htm', '2025') ON CONFLICT (id) DO NOTHING;
