INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('81ba8b92-8017-55b7-b6cc-98190fb48452', 'Kedi Pençesi', 'Uncaria tomentosa', 'Alkaloidler, kinolik asit', 'Bağışıklık güçlendirme, antiviral etkiler', 'Anti-HIV ilaçlar (Proteaz inhibitörleri: Amprenavir, Nelfinavir, Ritonavir, Saquinavir', 'Vücut, HIV/AIDS için kullanılan ilaçları parçalayarak onlardan kurtulur. Kedi pençesi almak, vücudun bu ilaçları parçalama hızını azaltabilir. Bu durum, HIV/AIDS için kullanılan bazı ilaçların etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun. Sağlık uzmanınıza danışın.', 'RxList. Cat’s Claw (Uncaria tomentosa) – Health Benefits, Side Effects, Uses, Dose & Precautions, Interactions. RxList. Updated 2025. Accessed September 8, 2025.', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('0ff18d4a-ea73-574b-8c55-ee9461dfe9f7', 'Kedi Pençesi', 'Uncaria tomentosa', 'Alkaloidler, kinolik asit', 'Bağışıklık güçlendirme, antiviral etkiler', 'Antihipertansif ilaçlar (Kalsiyum kanal blokörleri, ACE inhibitörleri, ARB, Diüretikler, Beta blokörler gibi)', 'Kedi pençesi rinkofilin içerir. İn vitro ve hayvan araştırmaları, rinkofilinin kan basıncını düşürebileceğini göstermektedir. Kedi pençesini kan basıncını düşüren ilaçlarla birlikte almak, kan basıncının çok düşmesine neden olabilir.', 'X', 'X', 'Kedi pençesi kan basıncını düşürebilir. Kedi pençesini kan basıncını düşüren ilaçlarla birlikte almak, kan basıncının çok düşmesine neden olabilir. Bazı kaynaklar, antihipertansif ilaç kullanımında(özellikle kalsiyum kanal blokörleri) kedi pençesi kullanılmamasını önermektedirler.', '1. WebMD. Cat’s Claw: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-395/cats-claw#interactions 2. HelloPharmacist. Cat’s Claw (Uncaria tomentosa) Drug–Supplement Interactions. HelloPharmacist. Accessed September 8, 2025. https://hellopharmacist.com/drug-supplement-interactions/herbals/cats-claw 3. RxList. Cat’s Claw (Uncaria tomentosa) – Health Benefits, Side Effects, Uses, Dose & Precautions, Interactions. RxList. Updated 2025. Accessed September 8, 2025.', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('185cefa6-3eac-56a7-af73-fb9203c844d2', 'Kedi Pençesi', 'Uncaria tomentosa', 'Alkaloidler, kinolik asit', 'Bağışıklık güçlendirme, antiviral etkiler', 'Antikoagülan ve antiplatelet ilaçlar', 'Kedi pençesi kan pıhtılaşmasını yavaşlatabilir. Kedi pençesini kan pıhtılaşmasını yavaşlatan ilaçlarla birlikte almak morarma ve kanama riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun. Sağlık uzmanınıza danışın.', '1. WebMD. Cat’s Claw: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-395/cats-claw#interactions 2. HelloPharmacist. Cat’s Claw (Uncaria tomentosa) Drug–Supplement Interactions. HelloPharmacist. Accessed September 8, 2025. https://hellopharmacist.com/drug-supplement-interactions/herbals/cats-claw 3. RxList. Cat’s Claw (Uncaria tomentosa) – Health Benefits, Side Effects, Uses, Dose & Precautions, Interactions. RxList. Updated 2025. Accessed September 8, 2025.', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('f283a9ec-7411-5a7d-b339-76c928b937fb', 'Kedi Pençesi', 'Uncaria tomentosa', 'Alkaloidler, kinolik asit', 'Bağışıklık güçlendirme, antiviral etkiler', 'İmmunsupresan ilaçlar: (azatiyoprin, siklosporin, mikofenolat, takrolimus, sirolimussteroidler, kemoterapötikler)', 'İnsan ve laboratuvar araştırmalarında, kedi pençesinin immünostimüle edici etkiye sahip olduğu gösterilmiştir. Fagositozu uyarır, solunum hücresi aktivitesini ve lökositlerin hareketliliğini artırır. Teorik olarak, bu durum immünosüpresif ilaçların aktivitesini etkileyebilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun. Sağlık uzmanınıza danışın.', '1. WebMD. Cat’s Claw: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-395/cats-claw#interactions 2. HelloPharmacist. Cat’s Claw (Uncaria tomentosa) Drug–Supplement Interactions. HelloPharmacist. Accessed September 8, 2025. https://hellopharmacist.com/drug-supplement-interactions/herbals/cats-claw 3. RxList. Cat’s Claw (Uncaria tomentosa) – Health Benefits, Side Effects, Uses, Dose & Precautions, Interactions. RxList. Updated 2025. Accessed September 8, 2025.', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('20fc7b47-57f4-573c-803a-a91cf5139018', 'Kedi Pençesi', 'Uncaria tomentosa', 'Alkaloidler, kinolik asit', 'Bağışıklık güçlendirme, antiviral etkiler', 'Sitokrom P450 3A4 (CYP3A4) substratları', 'Bazı ilaçlar karaciğer tarafından değiştirilir ve parçalanır. Kedi pençesi, karaciğerin bazı ilaçları parçalama hızını azaltabilir. Kedi pençesini karaciğer tarafından parçalanan bazı ilaçlarla birlikte almak, bazı ilaçların etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Kedi pençesini kullanmadan önce, karaciğer tarafından değiştirilen herhangi bir ilaç kullanıyorsanız sağlık uzmanınızla görüşün.', '1. WebMD. Cat’s Claw: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-395/cats-claw#interactions 2. HelloPharmacist. Cat’s Claw (Uncaria tomentosa) Drug–Supplement Interactions. HelloPharmacist. Accessed September 8, 2025. https://hellopharmacist.com/drug-supplement-interactions/herbals/cats-claw 3. RxList. Cat’s Claw (Uncaria tomentosa) – Health Benefits, Side Effects, Uses, Dose & Precautions, Interactions. RxList. Updated 2025. Accessed September 8, 2025.', '2025') ON CONFLICT (id) DO NOTHING;
