INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('954b12f9-6d66-5f61-9c71-2ddbde08957c', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Afatinib', 'Sarı kantaron, p-glikoprotein pompasını indükler. Afatinibin düzeyinin azalmasına neden olur.', 'X', 'X', 'Doktorunuza danışınız. Afatinib ile P-glikoprotein (P-gp) indükleyicilerinin kronik eş zamanlı uygulanması gereken hastalarda afatinib dozu, tolere edildiği şekilde 10 mg artırılmalıdır. Doz, P-gp indükleyicisinin kesilmesinden 2-3 gün sonra orijinal afatinib dozuna düşürülmelidir.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('c4ddec30-fb30-5778-b6ee-ae7f66c258cb', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Alfentanil', 'Sarı kantaron alfentanilin metabolizasyonunu artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Doktorunuza danışınız. Alfentanil ve orta etkili CYP3A4 indükleyicilerinin eş zamanlı kullanımı gerekiyorsa, stabil ilaç etkileri elde edilene kadar alfentanil dozunun artırılması düşünülmelidir. Hastalar opioid yoksunluğu belirtileri açısından izlenmelidir. Tersine, orta etkili bir CYP3A4 indükleyicisi kesilirse, stabil ilaç etkileri elde edilene kadar alfentanil dozunun azaltılması ve solunum depresyonu ve sedasyon gibi artmış opioid etkileri açısından izlenmesi düşünülmelidir.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('2304261b-05e4-589d-9f0b-c5278b1275e4', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Atorvastatin, Lovastatin, Simvastatin,', 'Sarı kantaron bu ilaçların metabolizasyonlarını artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'HMG-CoA redüktaz inhibitörlerinin (statinler) potansiyel etki azalmasından kaçınmak için, sarı kantaronun atorvastatin, lovastatin ve simvastatin ile eş zamanlı kullanımından kaçınılmalıdır. Eş zamanlı kullanım durumunda, statin etkinliğinin azalması açısından takip edilmelidir. Fluvastatin, pitavastatin, pravastatin ve rosuvastatin, CYP3A4 tarafından metabolize edilmeyen alternatif HMG-CoA redüktaz inhibitörleridir (statinler).', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('2ac1c71d-0b66-54c5-8a09-3e245ce6133a', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'CYP3A4 Substratları: Abemasiklib, Ombitasvir, Paritaprevir ve Ritonavir, Ombitasvir, Paritaprevir, Ritonavir, Dasabuvir, atazanavir, atrasentan , Avakopan, Avanafil, Avapritinib, Aksitinib, Bedaquilin, Bictegravir, Brigatinib, Kabozantinib, Capivasertib, Kapmatinib, Kariprazin, Kobisistat, Kobimetinib, Apiksaban, Dagibatran, Dolutegravir, Doksorubusin, Kaftor grubu ilaçlar, Esomeprazol, Tirozin kinaz inhibitörleri, Lansoprazol, Omeprazol, Ivabradin, Ranolazin, Ritonavir, Rivaroksaban,Sirolimus, Tenofovir Alefenamid,  Vinkristin, Vorikonazol, Zolpidem', 'Sarı kantaron bu ilaçların metabolizasyonlarını artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Birlikte kullanımdan kaçınılmalıdır.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('2637e60c-f501-50d8-9ce7-ee9ac5dabfd9', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Edoksaban', 'Sarı kantaron edoksabanın metabolizasyonunu artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Mümkünse edoksaban ve P-glikoprotein (P-gp) indükleyicilerinin birlikte uygulanmasından kaçının. Eş zamanlı kullanım gerekiyorsa, edoksaban etkinliğinin veya edoksaban (veya edoksaban metaboliti) serum konsantrasyonlarının azalması açısından izleyin. Edoksaban maruziyetinde maksimum azalmanın, P-gp indükleyicisinin birden fazla dozu uygulandıktan sonra, tedaviye başlandıktan sonraki günler ila haftalar içinde gerçekleşmesi beklenir. İndüksiyon etkileri, indükleyicinin kesilmesinden sonra da günler ila haftalar boyunca devam edebilir.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('9d7db032-3c87-58c7-b982-01244ef82e02', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Everolimus', 'Sarı kantaron everolimusun metabolizasyonunu artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Birlikte kullanımdan kaçınılmalıdır.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('e27655ef-31fb-5cee-9c88-c7fa89c4c3c5', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'İrinotekan', 'Sarı kantaron bu ilaçların metabolizasyonlarını artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'İrinotekan tedavisi sırasında sarı kantaron kullanımından kaçınılmalı ve mümkünse irinotekan tedavisine başlamadan en az 2 hafta önce CYP3A4 indükleyici olmayan ajanların yerine başka ajanlar kullanılması düşünülmelidir. Bu ajanların birlikte kullanılması gerekiyorsa, irinotekan etkinliğinin azalması açısından takip edilmelidir.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('e4d10264-01e6-583d-99a5-f89706a92789', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'K Vitamini antagonistleri (varfarin)', 'Sarı kantaron bu ilaçların metabolizasyonlarını artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'K vitamini antagonistleriyle tedavi edilen hastalarda sarı kantaron kullanımından kaçınılması düşünülmelidir. Sarı kantaron başlandığında/doz artırıldığında antikoagülan etkilerin azalması (örn. INR''de azalma, tromboembolik olaylar) veya sarı kantaron kesildiğinde/doz azaltıldığında antikoagülan etkilerin artması (örn. INR''de artış, kanama) açısından izlenmelidir.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('377dbf71-baec-5bdf-9ebc-3d7851c2fd5d', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Ketiapin', 'Sarı kantaron bu ilaçların metabolizasyonlarını artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Sarı kantaron ile kronik tedavi sırasında (örneğin 7-14 günden fazla) terapötik faydanın sürdürülmesi için ketiapin dozunun normal dozun 5 katına kadar artırılması gerekebilir. Doz, hastanın klinik yanıtına ve toleransına göre titre edilmelidir. Ketiapin dozu, sarı kantaronun kesilmesinden sonraki 7-14 gün içinde önceki/normal doza düşürülmelidir.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('d897e80d-0836-56c5-95e6-e3a99bffd876', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Klaritromisin', 'Sarı kantaron klaritromisinin metabolizasyonunu artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Alternatif antimikrobiyal düşünülmelidir.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('03fe65e7-30fd-54b0-96a4-133ab4da0289', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Kontraseptif ilaçlar', 'Sarı kantaron bu ilaçların metabolizasyonlarını artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Doğum kontrolü başarısızlığı mümkündür. Hormonal kontraseptif kullanan bir hastada orta şiddette bir CYP3A4 indükleyici kullanılması gerekiyorsa, hastalara eş zamanlı uygulama sırasında alternatif bir doğum kontrol yöntemi veya yedek bir yöntem kullanmaları ve kontraseptif güvenilirliğini sağlamak için orta şiddette CYP3A4 indükleyicisinin kesilmesinden sonra 28 gün boyunca yedek doğum kontrolüne devam etmeleri tavsiye edilmelidir. Birçok hormonal kontraseptifin etkisinin azaldığına dair önemli bir işaret olsa da, ara kanamanın bir etkileşim meydana gelmesine rağmen mevcut olmayabileceği unutulmamalıdır.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('070b4ea5-3bc1-58ef-b7dc-0e70768c95d8', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Siklosporin', 'Sarı kantaron siklosporinin metabolizasyonunu artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Birlikte kullanımdan kaçınılmalıdır.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('dbcbd24d-1869-5caa-b3eb-47c8d56f81bb', 'Sarı Kantaron', 'Hypericum perforatum', 'Fenolik bileşikler', 'Yara ve yanık tedavisi, depresyon', 'Taktolimus', 'Sarı kantaron bu ilaçların metabolizasyonlarını artırarak, kan düzeylerini azaltabilir.', 'X', 'X', 'Sarı kantaron ve takrolimusun birlikte kullanımından kaçınılmalıdır. Birlikte kullanılıyorsa, sarı kantaron başlandığında/doz artırıldığında serum takrolimus konsantrasyonlarının azaldığını, sarı kantaron kesildiğinde/doz azaltıldığında ise serum takrolimus konsantrasyonlarının arttığını gözlemleyin.', 'Drug Interactions. In: UpToDate, Connor RF (Ed), Wolters Kluwer. Accessed September 8, 2025. https://www.uptodate.com/drug-interactions/?source=responsive_home#di-analyze', '2025') ON CONFLICT (id) DO NOTHING;
