INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('567261c7-ecfa-5037-84a0-493c098f2ad1', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', '5-florourasil', '5-florourasil ile birlikte büyük miktarda yeşil çay tüketmek, 5-florourasil seviyelerini artırabilir. Bu da 5-florourasil''in etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('aae2412c-5f51-549c-b719-cc27849f9777', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Adenozin', 'Yeşil çay kafein içerir. Yeşil çaydaki kafein, doktorlar tarafından kardiyak stres testi adı verilen bir test yapmak için sıklıkla kullanılan adenozinin etkilerini engelleyebilir.', 'X', 'X', 'Kardiyak stres testinden en az 24 saat önce yeşil çay tüketmeyi bırakın.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('65d9ebc5-fd0d-53ea-b4aa-34c1cd6f831c', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Antikoagülan ve antiplatelet ilaçlar', 'Yeşil çay kanın pıhtılaşmasını yavaşlatabilir. Yeşil çayı kanın pıhtılaşmasını yavaşlatan ilaçlarla birlikte almak morarma ve kanama riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('bcae45b0-2a43-511b-8b16-8b3ac09db534', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Atorvastatin', 'Yeşil çay özütü, vücudun atorvastatin emilimini azaltabilir. Yeşil çay özünü atorvastatin ile birlikte almak, atorvastatinin etkilerini azaltabilir.', 'X', 'X', 'Bu kombinasyonu almayın', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('850a7e06-06ca-530d-94d2-c2b16775a87c', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Beta-2 agonist ilaçlar', 'Yeşil çay kafein içerir. Kafein kalbi uyarabilir. Bazı astım ilaçları da kalbi uyarabilir. Bazı astım ilaçlarıyla birlikte kafein almak aşırı uyarılmaya ve kalp sorunlarına yol açabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('bd2c6833-5201-598a-b82f-1cf07fc368ae', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Bortezomib', 'Bortezomib belirli kanser türlerinde kullanılır. Yeşil çay, bortezomib ile etkileşime girerek etkilerini azaltabilir.', 'X', 'X', 'Bortezomib kullanıyorsanız, yeşil çay ürünleri kullanmaktan kaçının.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('35019b95-3d0b-559d-960b-dc438c734989', 'Yeşil Çay', 'Camellia sinensis (L.) Kuntze', 'Flavonoidler, tanenler', 'Antioksidan, yağ emilimini azaltıcı', 'D kategorisi: Afatinib, bortezomib, edoksaban, lefamulin, linagliptin, paliperidon, sirolimus, tenofovir alafenamid', 'P-glikoprotein/ABCB1 indüksiyonu ile ilaç etkinliği azalabilir.', 'yok', 'D kategorisi ilaç alan hastalar', 'P-glikoprotein indükleyicisine alternatif tedavi değerlendirin. Kombinasyon zorunluysa ilaç etkinliğini yakından izleyin.', '1. Gilotrif [product labeling]. Boehringer Ingelheim, Jan 2018. 2. Vemlidy [product labeling]. Gilead Sciences, Sep 2021. 3. Savaysa [product labeling]. Daiichi Sankyo, Sep 2017.', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('6eda2b57-4686-5502-a930-dfc3091e6efe', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Dipiramidol', 'Yeşil çay kafein içerir. Yeşil çaydaki kafein, dipiridamolün etkilerini engelleyebilir. Dipiridamol, doktorlar tarafından genellikle kardiyak stres testi adı verilen bir kalp testi yapmak için kullanılır.', 'X', 'X', 'Kardiyak stres testinden en az 24 saat önce yeşil çay içmeyi bırakın.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('d6320b85-3a1b-5386-812e-4c1d93271290', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Disülfiram', 'Vücut, kafeinden kurtulmak için onu parçalar. Disülfiram, vücudun kafeinden kurtulma hızını azaltabilir. Disülfiram ile birlikte yeşil çay almak, kafeinin sinirlilik, hiperaktivite, asabiyet ve benzeri etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('00d2e029-d8fe-51ca-8a67-d6938b6d9546', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Diüretikler', 'Yeşil çay kafein içerir. Kafein, özellikle büyük miktarlarda alındığında vücuttaki potasyum seviyelerini düşürebilir. Diüretikler de vücuttaki potasyumu azaltabilir. Diüretikler ile birlikte büyük miktarda kafein almak, vücuttaki potasyumu çok fazla azaltabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('bdf7fd4c-322a-5872-af92-e9f43b5cbf93', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Efedrin', 'Yeşil çay kafein içerir. Kafein ve efedrin uyarıcı ilaçlardır. Yeşil çayı efedrinle birlikte almak aşırı uyarılmaya ve bazen ciddi yan etkilere ve kalp sorunlarına neden olabilir.', 'X', 'X', 'Kafein içeren ürünler ve efedrini aynı anda almayın.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('9024a7f5-9554-5177-949b-df1574218e2e', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Etosüksimid', 'Yeşil çaydaki kafein, etosuksimidin etkilerini azaltabilir. Yeşil çayı etosuksimid ile birlikte almak, etosuksimidin etkilerini azaltabilir. Bu da nöbet riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('420cc719-0602-5440-8c44-6323965f3dc9', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Feksofenadin', 'Yeşil çay, vücudun feksofenadin emilimini azaltabilir.', 'X', 'X', 'Bu ilacı yeşil çay tüketiminden ayrı olarak tüketin.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('a11677fb-7cbb-539d-9cca-6a3d36c3d867', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Felbamat', 'Yeşil çaydaki kafein, bazı kişilerde felbamatın etkilerini azaltabilir ve nöbet riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('9b821fd7-3471-5030-8a4a-7ade7533d9c9', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Fenilpropanolamin', 'Yeşil çay kafein içerir. Kafein vücudu uyarabilir. Fenilpropanolamin de vücudu uyarabilir. Yeşil çay ve fenilpropanolamini birlikte almak aşırı uyarılmaya neden olabilir, kalp atış hızını ve kan basıncını artırabilir ve gerginliğe yol açabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('d218003d-8558-558d-85a0-20513c45b5c4', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Fenitoin', 'Yeşil çaydaki kafein, fenitoinin etkilerini azaltabilir. Yeşil çayı fenitoinle birlikte almak, bazı kişilerde fenitoinin etkilerini azaltabilir ve nöbet riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('23a6d99a-bf9d-5e5c-a015-631edfcbec0b', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Fenobarbital', 'Yeşil çaydaki kafeinin uyarıcı etkisi, pentobarbitalin uyku getirici etkisini bloke edebilir. Ayrıca, yeşil çaydaki kafein, fenobarbitalin etkilerini azaltabilir ve bazı kişilerde nöbet riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('0d9dbaa7-44d1-51d3-b3d3-867fd724c0f4', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Florokinolonlar', 'Bazı antibiyotikler, vücudun kafeini parçalama hızını azaltabilir. Bu antibiyotikleri yeşil çayla birlikte almak, sinirlilik, baş ağrısı, kalp atış hızında artış ve diğer yan etkiler gibi yan etki riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('069db32e-36ca-559e-bb28-4fd7bbd582de', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Fluvoksamin', 'Vücut, yeşil çaydaki kafeini parçalayarak ondan kurtulur. Fluvoksamin, vücudun kafeini parçalama hızını azaltabilir. Fluvoksamin''i yeşil çayla birlikte almak, sinirlilik, baş ağrısı, hızlı kalp atışı gibi kafein yan etkilerinin riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('a6e481ec-793f-5ec9-aadb-b016f95019dd', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'İmatinib', 'Yeşil çayın, vücuda giren imatinib miktarını azalttığı görülmektedir. Bu durum, imatinib''in etkilerini azaltabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('e419be9e-4a24-551d-87dc-9f951f70e8ef', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Karbamazepin', 'Kafein, karbamazepinin etkilerini azaltabilir. Yeşil çay kafein içerdiğinden, yeşil çayı karbamazepinle birlikte almak karbamazepinin etkilerini azaltabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('647648c9-f4e4-57dd-9a34-c887d1e43c5b', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Klozapin', 'Vücut, klozapini parçalayarak ondan kurtulur. Yeşil çaydaki kafein, vücudun klozapinin parçalanma hızını azaltıyor gibi görünmektedir. Yeşil çayı klozapinle birlikte almak, klozapinin etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('8590363c-0b6f-5b5e-a5de-adeb9f1f0628', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Kontraseptif ilaçlar', 'Yeşil çay kafein içerir. Vücut, kafeini parçalayarak ondan kurtulur. Doğum kontrol hapları, vücudun kafeini parçalama hızını azaltabilir. Bu durum, kafeinin sinirlilik, baş ağrısı ve hızlı kalp atışı gibi yan etki riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('fe22013f-6618-506c-bce2-5d1d5c8611f1', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Lisinopril', 'Yeşil çayın, vücuttaki lisinopril emilimini azalttığı görülmektedir. Bu durum, lisinopril''in etkilerini azaltabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('86b2ba84-c897-5ed2-b360-b3198d0b401d', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Lityum', 'Yeşil çaydaki kafein, vücudun lityumdan kurtulma hızını artırabilir.', 'X', 'X', 'Kafein içeren ürünler kullanıyorsanız ve lityum kullanıyorsanız, kafeini birdenbire bırakmayın. Günlük kafein dozunu yavaşça azaltın. Kafeini çok hızlı bırakmak, lityumun yan etkilerini artırabilir.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('0c15a10c-f052-5298-8c3e-d759ab1b9f4a', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'MAO inhibitörleri (rasajilin, selejilin gibi)', 'Yeşil çay kafein içerir. Kafeinin MAOI adı verilen bazı ilaçlarla etkileşime girebileceği konusunda bazı endişeler vardır. Kafein bu ilaçlarla birlikte alındığında, hızlı kalp atışı ve çok yüksek tansiyon gibi ciddi yan etki riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('04b8bb35-8b73-5a6a-b286-3a2419805966', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Nadolol', 'Yeşil çay, vücudun nadolol emilimini azaltabilir. Yeşil çayı nadolol ile birlikte almak, nadololün etkilerini azaltabilir.', 'X', 'X', 'Bu kombinasyonu almayın', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('1ca8b252-0ddd-52c9-bab9-76e4c597fc7c', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Nikotin', 'Nikotin gibi uyarıcı ilaçlar sinir sistemini hızlandırır. Yeşil çaydaki kafein de sinir sistemini hızlandırabilir. Yeşil çayı uyarıcı ilaçlarla birlikte almak, kalp atış hızının artması ve yüksek tansiyon gibi ciddi sorunlara neden olabilir.', 'X', 'X', 'Uyarıcı ilaçları kafeinle birlikte almaktan kaçının.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('dc15024d-99e5-5faa-9774-7d3cf99d9a77', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Pioglitazon', 'Yeşil çay kafein içerir. Kafein, vücudun emdiği pioglitazon miktarını artırabilir. Yeşil çay içmek, pioglitazonun etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('f190154c-d60b-5233-a506-ea3f274d5893', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Riluzol', 'Yeşil çay içmek, vücudun riluzolü parçalama hızını azaltabilir ve riluzolün etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('5975a2f0-422f-53ef-93ae-66e9e4838e61', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Rosuvastatin', 'Yeşil çay özütü almak, kandaki rosuvastatin miktarını değiştirebilir. Bu da rosuvastatinin etkilerini ve yan etkilerini değiştirebilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('55865dfe-9c3a-58d5-b6e0-cfedbc53b543', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Simetidin', 'Yeşil çay kafein içerir. Vücut, kafeini parçalayarak ondan kurtulur. Simetidin, vücudun kafeini parçalama hızını azaltabilir. Simetidin''i yeşil çayla birlikte almak, sinirlilik, baş ağrısı, hızlı kalp atışı gibi kafein yan etkilerinin riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('fe047c75-82dd-5c1e-9034-3ca2fd6f9381', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Stimulanlar (Amfetamin, Kokain)', 'Uyarıcı ilaçlar sinir sistemini hızlandırarak kan basıncını yükseltebilir ve kalp atış hızını artırabilir. Yeşil çay kafein içerir. Kafein de sinir sistemini hızlandırabilir. Yeşil çayı uyarıcı ilaçlarla birlikte almak, kalp atış hızının artması ve yüksek tansiyon gibi ciddi sorunlara neden olabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('d13df9c3-4cdd-5eed-aca0-d2df1ff001a7', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Teofilin', 'Yeşil çay kafein içerir. Kafein, teofilinle benzer şekilde çalışır. Kafein ayrıca vücudun teofilinden kurtulma hızını da azaltabilir. Yeşil çayı teofilinle birlikte almak, teofilinin etkilerini ve yan etkilerini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('b6db2eda-e7a7-5080-8c65-36fefbcfe2d5', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Valproik asit', 'Yeşil çaydaki kafein valproatın etkisini azaltabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('8d3a0df5-0d2f-5170-b803-5bc2947a7dc7', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Varfarin', 'Yeşil çay K vitamini içerir. K vitamini, varfarinin etkisini azaltabilir. Ancak yeşil çaydaki K vitamini miktarı çok azdır. Bu nedenle, ölçülü tüketildiğinde yeşil çayın varfarin ile etkileşime girmesi olası değildir.', 'X', 'X', 'Günde 8 fincan veya daha fazla gibi büyük miktarlarda yeşil çay içmekten kaçınılmalıdır.', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.food_interactions (id, food_name, latin_name, active_ingredient, pharmacological_effect, interacting_drugs, mechanism, onset, risk_groups, management, sources, updated_at_source) VALUES ('51690774-7fbc-56a4-89b4-359ada459ffa', 'Yeşil Çay', 'Camellia sinensis', 'Kateşinler, flavonoidler, tanenler', 'Metabolizma hızlandırıcı, antioksidan, diyabet, kolesterol düşürücü', 'Verapamil', 'Verapamil, vücudun kafeinden kurtulma hızını azaltabilir. Yeşil çay içmek ve verapamil almak, sinirlilik, baş ağrısı ve kalp atış hızında artış gibi kafein yan etkilerinin riskini artırabilir.', 'X', 'X', 'Bu kombinasyona karşı dikkatli olun', 'WebMD. Green Tea: Overview, Uses, Side Effects, Precautions, Interactions, Dosing. WebMD. Updated 2025. Accessed September 8, 2025. https://www.webmd.com/vitamins/ai/ingredientmono-960/green-tea#interactions', '2025') ON CONFLICT (id) DO NOTHING;
